'use strict';

// Fix broken TOC/table anchors caused by hexo-renderer-marked's
// URL-encoding (encodeURI) of Chinese in URL fragments inside list
// items and table cells, while heading IDs (generated by
// hexo-util/slugize) keep Chinese as-is.
//
// Strategy: after post render, walk every <a href="#frag">, decode +
// slugize the fragment the same way heading IDs are generated, and
// rewrite the href to match a real heading id. If no match, leave it.

const slugize = require('hexo-util/lib/slugize');

function collectHeadingIds(html) {
  const ids = new Set();
  const re = /<h[1-6] id="([^"]+)"/g;
  let m;
  while ((m = re.exec(html)) !== null) {
    ids.add(m[1]);
  }
  return ids;
}

function rewriteAnchors(html) {
  const headingIds = collectHeadingIds(html);
  if (headingIds.size === 0) return html;

  return html.replace(
    /<a\s+href="#([^"]+)"([^>]*)>/gi,
    (match, fragment, rest) => {
      if (headingIds.has(fragment)) return match;

      let decoded;
      try {
        decoded = decodeURIComponent(fragment);
      } catch (e) {
        return match;
      }
      if (headingIds.has(decoded)) {
        return `<a href="#${decoded}"${rest}>`;
      }

      const slugified = slugize(decoded);
      if (headingIds.has(slugified)) {
        return `<a href="#${slugified}"${rest}>`;
      }
      return match;
    }
  );
}

hexo.extend.filter.register('after_post_render', function (data) {
  if (data && typeof data.content === 'string') {
    data.content = rewriteAnchors(data.content);
  }
  return data;
});
